		hud_banner.add_theme_color_override("font_color",
			Color(1.0, 0.35, 0.35) if kind == "reject" else (Color(0.5, 1.0, 0.6) if kind == "ok" else Color(1.0, 0.9, 0.45)))
		banner_until_ms = Time.get_ticks_msec() + 3500
	if shot != "":
		take_screenshot(shot)

